// 本人婚议有限页只显示实际已听到的节点和双方原经历；全局死亡不会自动变成人物知识。
#include "family_marriage_commands.hpp"
#include "resident/views/common_presentation.hpp"
#include <algorithm>
namespace hanmo::resident {namespace {
using V=BoundaryValue;
// 页码固定16条，返回值不会把全域婚姻账交给表现层。
V::Array slice(V::Array rows,Integer page){V::Array out;for(Integer i=page*16;i<std::min<Integer>(rows.size(),page*16+16);++i)out.push_back(std::move(rows[static_cast<std::size_t>(i)]));return out;}
// 展示只含原身份名称，不能夹带远方位置、存活或钱包字段。
V person(const CommonStore& c,const CommonCatalog& catalog,const StableId& id){auto named=CommonPresentation(c.state(),catalog).display_name(id);return boundary::obj({{"actor_id",V{id}},{"name",V{named.ok?named.value:id}}});}
// 每次有限页绑定完整读戳，界面可拒换人、读档或异步旧结果。
V identity(const CommonStore& c){StableId world;const char* h="0123456789abcdef";for(auto b:c.state().identity.world_id){world+=h[b>>4];world+=h[b&15];}const auto& i=c.state().identity;return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{i.execution_epoch}},{"revision",V{i.revision}},{"tick",V{i.tick}}});}
}
Outcome<BoundaryValue> query_family_marriage_page(const CommonStore& c,const CommonCatalog& common,const FamilyState& family,const FamilyDeathState& death,const InteractionState& meeting,const InteractionCatalog& interaction,const InteractionAccess& contact,const MarriageSourceCatalog& catalog,const FamilyMarriageState& state,const MarriageAccess& access,Integer page){using namespace boundary;if(!catalog.enabled)return {false,{},common_failure("MarriageProfileRequired").error};if(page<0||page>4095)return {false,{},common_failure("InvalidMarriagePage").error};auto history=validate_family_marriage(c,family,death,interaction,catalog,state,access);if(!history.ok)return {false,{},history.error};const auto& actor=c.state().metadata.player_actor_id;V::Array current,proposals,bonds;
    for(const auto& row:catalog.statements.rows()){if(row.second.listener_actor_id!=actor)continue;auto observed=preview_marriage_statement(c,meeting,interaction,contact,catalog,actor,row.first);if(!observed.ok)continue;FamilyMarriageCommand command;command.statement_id=row.first;if(row.second.intent=="offer_marriage")command.kind="family_marriage_receive";else{const auto* bond=history.value.active_by_actor.find(actor);if(!bond||bond->authored_origin)continue;command.kind="family_marriage_dissolve";command.marriage_id=bond->id;}auto quote=preview_family_marriage_command(c,family,death,meeting,interaction,contact,catalog,state,access,actor,command);current.push_back(obj({{"statement_id",V{row.first}},{"other",person(c,common,row.second.speaker_actor_id)},{"intent",V{row.second.intent}},{"command",V{command.kind}},{"marriage_id",V{command.marriage_id}},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}}}));}
    for(const auto& row:state.proposals.rows()){const auto& p=row.second.source;if(p.listener_actor_id!=actor&&p.speaker_actor_id!=actor)continue;StableId replied;for(const auto& answer:state.replies.rows())if(answer.second.proposal_id==row.first)replied=answer.second.decision;V::Array options;if(replied.empty()){const auto decisions=p.listener_actor_id==actor?std::vector<StableId>{"accepted","refused"}:std::vector<StableId>{"withdrawn"};for(const auto& choice:decisions){FamilyMarriageCommand command;command.kind="family_marriage_reply";command.proposal_id=row.first;command.decision=choice;auto quote=preview_family_marriage_command(c,family,death,meeting,interaction,contact,catalog,state,access,actor,command);options.push_back(obj({{"decision",V{choice}},{"available",V{quote.ok}},{"code",V{quote.ok?StableId{}:quote.error.original.code}}}));}}proposals.push_back(obj({{"proposal_id",V{row.first}},{"other",person(c,common,p.listener_actor_id==actor?p.speaker_actor_id:p.listener_actor_id)},{"received_tick",V{p.tick}},{"response",V{replied}},{"options",V{std::move(options)}}}));}
    for(const auto& row:state.replies.rows()){const auto& reply=row.second;if(reply.decision!="accepted"||!reply.confirmation)continue;const auto& s=*reply.confirmation;if(s.listener_actor_id!=actor&&s.speaker_actor_id!=actor)continue;StableId dissolved;Integer ended_tick=0;for(const auto& end:state.dissolutions.rows())if(end.second.marriage_id==row.first){dissolved=end.first;ended_tick=end.second.source.tick;}bonds.push_back(obj({{"marriage_id",V{row.first}},{"other",person(c,common,s.listener_actor_id==actor?s.speaker_actor_id:s.listener_actor_id)},{"formed_tick",V{reply.tick}},{"dissolution_fact_id",V{dissolved}},{"dissolved_tick",V{ended_tick}},{"status",V{dissolved.empty()?"recorded_marriage":"mutually_dissolved"}}}));}
    const auto* origin=catalog.origins.find(actor);const Integer current_count=current.size(),proposal_count=proposals.size(),bond_count=bonds.size();return {true,obj({{"actor_id",V{actor}},{"source_identity",identity(c)},{"page",V{page}},{"origin_status",V{origin?origin->status:StableId{"unknown"}}},{"statement_count",V{current_count}},{"proposal_count",V{proposal_count}},{"bond_count",V{bond_count}},{"current_statements",V{slice(std::move(current),page)}},{"proposals",V{slice(std::move(proposals),page)}},{"marriages",V{slice(std::move(bonds),page)}},{"explanation",V{"听取提议与本人接受分开办理；原财产、住处、公职与照护责任保持。这里显示本人原经历，不自动获得远方消息。"}}}),{}};
}
}
